/* SPDX-License-Identifier: GPL-3.0-only
 * ETCH V1.27: USB-qualified, staged analog-output startup; host-testable policy.
 * TIMER4 is 24MHz. Keep the DAC clocking *silence* before and after
 * releasing the PC6 codec/output enable. PCM ramps cannot mute a pop
 * generated by the analog power stage itself.
 */
#pragma once
#include <stdint.h>
#define ETCH_OUTPUT_CLOCK_SETTLE_TICKS 24000000u /* 1000ms at 24MHz */
#define ETCH_OUTPUT_ANALOG_SETTLE_TICKS 24000000u /* 1000ms at 24MHz */
/* Never release the PC6 analogue power edge while USB configuration/suspend
 * has changed recently. This is not a measurement of VBUS, the codec bias,
 * or any coupling capacitor: the PC6 edge itself may still be audible.
 * Do NOT time out into an unqualified analogue enable. */
#define ETCH_OUTPUT_USB_STABLE_TICKS 48000000u /* 2000ms at 24MHz */
struct etch_output_usb_gate { uint32_t changed_ticks; uint8_t observed; uint8_t valid; };
static inline void etch_output_usb_reset(struct etch_output_usb_gate *g){
 g->changed_ticks=0u;g->observed=0u;g->valid=0u;
}
static inline uint8_t etch_output_usb_ready(struct etch_output_usb_gate *g,
 uint32_t now,uint8_t usb_state){
 if(!g->valid || g->observed!=usb_state){
  g->observed=usb_state;g->changed_ticks=now;g->valid=1u;
  return 0u;
 }
 return (uint8_t)((uint32_t)(now-g->changed_ticks)>=ETCH_OUTPUT_USB_STABLE_TICKS);
}

#define ETCH_OUTPUT_MIN_DMA_HALVES 32u
#define ETCH_OUTPUT_RAMP_SAMPLES 8192u          /* ~186ms at 44.1kHz */
enum etch_output_phase { ETCH_OUTPUT_CLOCK_SILENCE=0, ETCH_OUTPUT_ANALOG_SILENCE=1, ETCH_OUTPUT_PLAY=2 };
enum etch_output_action { ETCH_OUTPUT_WAIT=0, ETCH_OUTPUT_ENABLE_ANALOG=1, ETCH_OUTPUT_ANALOG_READY=2 };
struct etch_output_gate { uint32_t phase_ticks; uint8_t phase; };
static inline void etch_output_gate_reset(struct etch_output_gate *g, uint32_t now){
 g->phase_ticks=now; g->phase=ETCH_OUTPUT_CLOCK_SILENCE;
}
static inline uint8_t etch_output_gate_advance(struct etch_output_gate *g,uint32_t now,uint32_t dma_halves){
 if(g->phase==ETCH_OUTPUT_CLOCK_SILENCE){
  if(dma_halves<ETCH_OUTPUT_MIN_DMA_HALVES ||
     (uint32_t)(now-g->phase_ticks)<ETCH_OUTPUT_CLOCK_SETTLE_TICKS)return ETCH_OUTPUT_WAIT;
  g->phase_ticks=now;g->phase=ETCH_OUTPUT_ANALOG_SILENCE;
  return ETCH_OUTPUT_ENABLE_ANALOG;
 }
 if(g->phase==ETCH_OUTPUT_ANALOG_SILENCE){
  if((uint32_t)(now-g->phase_ticks)<ETCH_OUTPUT_ANALOG_SETTLE_TICKS)return ETCH_OUTPUT_WAIT;
  g->phase=ETCH_OUTPUT_PLAY;return ETCH_OUTPUT_ANALOG_READY;
 }
 return ETCH_OUTPUT_WAIT;
}

/* V1.03: do not allow the first nonzero digital sample until AFTER
 * the main PLAY frame is fully transferred to LCD. The analog amplifier
 * still has a hardware-only enable edge; software cannot promise to
 * eliminate an inherent analog bias transient. */
#define ETCH_OUTPUT_SCREEN_QUIET_TICKS 12000000u /* 500ms at 24MHz */
#define ETCH_OUTPUT_SCREEN_TIMEOUT_TICKS 240000000u /* 10s */
struct etch_output_screen_gate {
 uint32_t started, quiet_since;
 uint8_t saw_analog_ready, ready, timed_out;
};
static inline void etch_output_screen_reset(struct etch_output_screen_gate *g,uint32_t now){
 g->started=now;g->quiet_since=now;
 g->saw_analog_ready=0;g->ready=0;g->timed_out=0;
}
static inline uint8_t etch_output_screen_advance(struct etch_output_screen_gate *g,
 uint32_t now,uint8_t audio_running,uint8_t analog_ready){
 if(g->ready)return 1u;
 if(!g->saw_analog_ready){
  if(audio_running && analog_ready){g->saw_analog_ready=1u;g->quiet_since=now;}
 }else if(!audio_running||!analog_ready){
  g->saw_analog_ready=0u;
 }else if((uint32_t)(now-g->quiet_since)>=ETCH_OUTPUT_SCREEN_QUIET_TICKS){
  g->ready=1u;return 1u;
 }
 if((uint32_t)(now-g->started)>=ETCH_OUTPUT_SCREEN_TIMEOUT_TICKS){
  g->timed_out=1u;g->ready=1u;return 1u;
 }
 return 0u;
}
/* A timed-out or incomplete startup must remain digitally muted. */
static inline uint8_t etch_output_may_unmute(uint8_t audio_running,uint8_t analog_ready,
 uint8_t screen_ready,uint8_t timed_out,uint8_t first_frame_rendered){
 return (uint8_t)(audio_running && analog_ready && screen_ready &&
                  !timed_out && first_frame_rendered);
}
